<script setup>
import{ref,onMounted}from'vue';import{api,json}from'../api';import{Plus,Pencil,Power,Trash2,Search}from'lucide-vue-next';import Modal from'../components/Modal.vue';import Toast from'../components/Toast.vue'
const rows=ref([]),categories=ref([]),name=ref(''),show=ref(false),form=ref({}),toast=ref('');async function load(){rows.value=await api(`/api/admin/dish/page${name.value?'?name='+encodeURIComponent(name.value):''}`)}async function cats(){categories.value=(await api('/api/admin/category/page?type=1')).filter(x=>x.status===1)}function edit(r={price:0,status:1,image:'',description:''}){form.value={...r};show.value=true}function msg(s){toast.value=s;setTimeout(()=>toast.value='',2200)}async function save(){await api('/api/admin/dish',{method:form.value.id?'PUT':'POST',body:json(form.value)});show.value=false;msg('Saved');load()}async function status(r){await api(`/api/admin/dish/${r.id}/status/${r.status?0:1}`,{method:'PATCH'});load()}async function remove(r){if(!confirm(`Delete dish "${r.name}"?`))return;await api(`/api/admin/dish/${r.id}`,{method:'DELETE'});msg('Deleted');load()}onMounted(()=>{load();cats()})
</script>
<template><div class="page-head"><div><h1>Dishes</h1><p>Manage dish prices, categories and sale status</p></div><button class="primary" @click="edit()"><Plus :size="18"/>Add Dish</button></div><div class="filters"><div class="search"><Search/><input v-model="name" placeholder="Search dish name" @keyup.enter="load"/></div><button class="secondary" @click="load">Search</button></div><div class="table-wrap"><table><thead><tr><th>Dish</th><th>Category</th><th>Price</th><th>Status</th><th class="actions">Actions</th></tr></thead><tbody><tr v-for="r in rows"><td><strong>{{r.name}}</strong><small>{{r.description||'No description'}}</small></td><td>{{categories.find(c=>c.id===r.categoryId)?.name||r.categoryId}}</td><td class="price">¥ {{r.price}}</td><td><span class="status" :class="r.status?'on':'off'">{{r.status?'On sale':'Disabled'}}</span></td><td class="actions"><button title="Edit" @click="edit(r)"><Pencil/></button><button title="Toggle status" @click="status(r)"><Power/></button><button title="Delete" class="danger" @click="remove(r)"><Trash2/></button></td></tr></tbody></table></div><Modal v-if="show" :title="form.id?'Edit Dish':'Add Dish'" @close="show=false"><form class="form-grid" @submit.prevent="save"><label>Dish Name<input v-model="form.name" required/></label><label>Category<select v-model.number="form.categoryId" required><option disabled value="">Select</option><option v-for="c in categories" :value="c.id">{{c.name}}</option></select></label><label>Price<input v-model.number="form.price" type="number" step="0.01" min="0.01" required/></label><label class="full">Description<textarea v-model="form.description" rows="3"/></label><footer><button type="button" class="secondary" @click="show=false">Cancel</button><button class="primary">Save</button></footer></form></Modal><Toast :message="toast"/></template>
